## Java-Komponenten

Die Utility-Klasse kapselt die gesamte sicherheitsrelevante Parser-Konfiguration:

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SecureXmlUtils.java
package com.example.customerxml.xml;

import javax.xml.XMLConstants;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import javax.xml.transform.stream.StreamSource;
import javax.xml.validation.Schema;
import javax.xml.validation.SchemaFactory;
import java.io.InputStream;
import org.xml.sax.SAXException;

/**
 * Zentrale Stelle fuer eine XXE-sichere und schema-validierende
 * XML-Parser-Konfiguration (siehe OWASP XXE Prevention Cheat Sheet).
 */
public final class SecureXmlUtils {

    private SecureXmlUtils() {
        // reine Utility-Klasse, keine Instanzen
    }

    /**
     * Erstellt eine gehaertete DocumentBuilderFactory:
     * - DOCTYPE-Deklarationen sind komplett verboten (primaere XXE-Abwehr)
     * - externe General-/Parameter-Entities werden nicht aufgeloest
     * - externe DTDs werden nicht nachgeladen
     * - XInclude und Entity-Expansion sind deaktiviert
     * - "Secure Processing" ist aktiviert (Schutz vor Billion-Laughs-DoS)
     * - striktes Schema (XSD) wird zur Pflicht-Validierung hinterlegt
     */
    public static DocumentBuilderFactory createSecureSchemaValidatingFactory(Schema schema)
            throws ParserConfigurationException {

        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();

        // Primaere Abwehr: DOCTYPE komplett verbieten.
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

        // Defense in depth, falls DOCTYPE in einer anderen Konfiguration
        // doch erlaubt werden muesste.
        dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
        dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        dbf.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);

        dbf.setXIncludeAware(false);
        dbf.setExpandEntityReferences(false);

        // Schuetzt zusaetzlich vor Ressourcen-Erschoepfung (Entity-Expansion etc.).
        dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

        // Strikte Validierung gegen das vordefinierte XSD erzwingen.
        dbf.setNamespaceAware(true);
        dbf.setValidating(false); // legacy DTD-Validation aus, wir nutzen setSchema()
        dbf.setSchema(schema);

        return dbf;
    }

    /**
     * Laedt das Kunden-XSD und haertet auch die SchemaFactory selbst gegen
     * XXE, indem jeglicher externer DTD-/Schema-Zugriff unterbunden wird.
     */
    public static Schema loadCustomerSchema(InputStream xsdStream) throws SAXException {

        SchemaFactory schemaFactory =
                SchemaFactory.newInstance(XMLConstants.W3C_XML_SCHEMA_NS_URI);

        schemaFactory.setProperty(XMLConstants.ACCESS_EXTERNAL_DTD, "");
        schemaFactory.setProperty(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");

        return schemaFactory.newSchema(new StreamSource(xsdStream));
    }
}
