Ein strikter `ErrorHandler`, der Validierungsfehler nicht verschluckt, sondern als Exception weiterreicht:

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// StrictXsdErrorHandler.java
package com.example.customerxml.xml;

import org.xml.sax.ErrorHandler;
import org.xml.sax.SAXException;
import org.xml.sax.SAXParseException;

/**
 * Erzwingt strikte XSD-Validierung: jede Warnung, jeder Fehler und jeder
 * Fatal Error fuehrt zum Abbruch des Parsevorgangs statt stillschweigend
 * ignoriert zu werden.
 */
public final class StrictXsdErrorHandler implements ErrorHandler {

    @Override
    public void warning(SAXParseException exception) throws SAXException {
        throw exception;
    }

    @Override
    public void error(SAXParseException exception) throws SAXException {
        throw exception;
    }

    @Override
    public void fatalError(SAXParseException exception) throws SAXException {
        throw exception;
    }
}
