Das Repository lädt die XML-Datei, validiert sie gegen das XSD und führt die sichere XPath-Suche durch:

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// CustomerXmlRepository.java
package com.example.customerxml.repository;

import com.example.customerxml.dto.CustomerDto;
import com.example.customerxml.exception.CustomerSearchException;
import com.example.customerxml.xml.SecureXmlUtils;
import com.example.customerxml.xml.StrictXsdErrorHandler;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.core.io.ClassPathResource;
import org.springframework.stereotype.Repository;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;
import org.xml.sax.SAXException;

import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.validation.Schema;
import javax.xml.xpath.XPath;
import javax.xml.xpath.XPathConstants;
import javax.xml.xpath.XPathExpression;
import javax.xml.xpath.XPathExpressionException;
import javax.xml.xpath.XPathFactory;
import java.io.IOException;
import java.io.InputStream;
import java.util.Optional;

/**
 * Laedt Kundendaten aus einer festen, im Classpath hinterlegten XML-Datei
 * und sucht dort per XPath nach einem Kunden. Der Dateipfad ist bewusst
 * NICHT aus Nutzereingaben ableitbar (schuetzt vor Path Traversal, CWE-22).
 */
@Repository
public class CustomerXmlRepository {

    private static final Logger log = LoggerFactory.getLogger(CustomerXmlRepository.class);

    private static final String CUSTOMER_XML_CLASSPATH = "data/customers.xml";
    private static final String CUSTOMER_XSD_CLASSPATH = "data/customers.xsd";

    private final Schema customerSchema;

    public CustomerXmlRepository() {
        try (InputStream xsdStream =
                     new ClassPathResource(CUSTOMER_XSD_CLASSPATH).getInputStream()) {
            this.customerSchema = SecureXmlUtils.loadCustomerSchema(xsdStream);
        } catch (IOException | SAXException e) {
            throw new IllegalStateException("Unable to load customer XSD schema", e);
        }
    }

    public Optional<CustomerDto> findByName(String customerName) {
        try (InputStream xmlStream =
                     new ClassPathResource(CUSTOMER_XML_CLASSPATH).getInputStream()) {

            DocumentBuilderFactory dbf =
                    SecureXmlUtils.createSecureSchemaValidatingFactory(customerSchema);

            DocumentBuilder builder = dbf.newDocumentBuilder();
            builder.setErrorHandler(new StrictXsdErrorHandler());

            Document document = builder.parse(xmlStream);

            return searchCustomerByName(document, customerName);

        } catch (Exception e) {
            // Details nur serverseitig loggen, dem Client generische
            // Fehlermeldung liefern (siehe CustomerSearchException).
            log.error("Failed to process customer XML data", e);
            throw new CustomerSearchException("Unable to process customer data", e);
        }
    }

    /**
     * Baut die XML-Suchanfrage sicher auf: der Kundenname wird als
     * XPath-Variable gebunden statt in den Ausdruck-String eingefuegt.
     * Das verhindert XPath Injection (CWE-643) analog zu Prepared
     * Statements bei SQL.
     */
    private Optional<CustomerDto> searchCustomerByName(Document document, String customerName)
            throws XPathExpressionException {

        XPathFactory xPathFactory = XPathFactory.newInstance();
        XPath xPath = xPathFactory.newXPath();

        xPath.setXPathVariableResolver(variableName -> {
            if ("customerName".equals(variableName.getLocalPart())) {
                return customerName;
            }
            return null;
        });

        XPathExpression expression =
                xPath.compile("/customers/customer[name=$customerName]");

        NodeList nodes = (NodeList) expression.evaluate(document, XPathConstants.NODESET);

        if (nodes.getLength() == 0) {
            return Optional.empty();
        }

        Element customerElement = (Element) nodes.item(0);
        return Optional.of(mapToDto(customerElement));
    }

    private CustomerDto mapToDto(Element customerElement) {
        String id = getChildTextContent(customerElement, "id");
        String name = getChildTextContent(customerElement, "name");
        String email = getChildTextContent(customerElement, "email");
        return new CustomerDto(id, name, email);
    }

    private String getChildTextContent(Element parent, String tagName) {
        NodeList children = parent.getElementsByTagName(tagName);
        if (children.getLength() == 0) {
            return null;
        }
        return children.item(0).getTextContent();
    }
}
