Die Service-Schicht kapselt die Fachlogik:

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// CustomerService.java
package com.example.customerxml.service;

import com.example.customerxml.dto.CustomerDto;
import com.example.customerxml.exception.CustomerNotFoundException;
import com.example.customerxml.repository.CustomerXmlRepository;
import org.springframework.stereotype.Service;

@Service
public class CustomerService {

    private final CustomerXmlRepository customerXmlRepository;

    public CustomerService(CustomerXmlRepository customerXmlRepository) {
        this.customerXmlRepository = customerXmlRepository;
    }

    public CustomerDto findCustomerByName(String customerName) {
        return customerXmlRepository.findByName(customerName)
                .orElseThrow(() ->
                        new CustomerNotFoundException("No customer found for the given name"));
    }
}
