Der REST-Controller mit zusätzlicher serverseitiger Eingabevalidierung:

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// CustomerController.java
package com.example.customerxml.controller;

import com.example.customerxml.dto.CustomerDto;
import com.example.customerxml.service.CustomerService;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/**
 * Der customerName-Parameter wird zusaetzlich zur sicheren XPath-Bindung
 * (siehe CustomerXmlRepository) serverseitig auf Laenge und erlaubte
 * Zeichen eingeschraenkt (Defense in Depth gegen CWE-20/CWE-643).
 */
@RestController
@Validated
public class CustomerController {

    private final CustomerService customerService;

    public CustomerController(CustomerService customerService) {
        this.customerService = customerService;
    }

    @GetMapping("/api/customers/search")
    public CustomerDto searchCustomer(
            @RequestParam("customerName")
            @NotBlank
            @Size(max = 100)
            @Pattern(
                    regexp = "^[\\p{L}\\p{N} .,'-]{1,100}$",
                    message = "customerName contains invalid characters"
            )
            String customerName) {

        return customerService.findCustomerByName(customerName);
    }
}
